class ReportAccumulator:
    def __init__(self):
        self._total_revenue = 0
        self._total_orders = 0
        self._total_items = 0
        self._max_order = 0
        self._min_order = float('inf')
        self._status_counts = {}
        self._product_revenue = {}

    def update(self, order):
        value = order['value']
        self._total_revenue += value
        self._total_orders += 1
        self._total_items += len(order['items'])
        self._max_order = max(self._max_order, value)
        self._min_order = min(self._min_order, value)

        status = order['status']
        self._status_counts[status] = self._status_counts.get(status, 0) + 1

        for item in order['items']:
            pid = item['product_id']
            self._product_revenue[pid] = (
                self._product_revenue.get(pid, 0) + item['price'] * item['qty']
            )

    @property
    def summary(self):
        return {
            'total_revenue': self._total_revenue,
            'total_orders': self._total_orders,
            'total_items': self._total_items,
            'avg_order_value': self._total_revenue / self._total_orders if self._total_orders else 0,
            'max_order': self._max_order,
            'min_order': self._min_order if self._min_order != float('inf') else 0,
            'status_counts': self._status_counts,
            'top_products': sorted(self._product_revenue.items(), key=lambda x: x[1], reverse=True)[:5],
        }


def generate_report(orders):
    accumulator = ReportAccumulator()
    for order in orders:
        accumulator.update(order)
    return accumulator.summary
